namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public int DepartmentId { get; set; }
    public Department Department { get; set; } = new();
    public Instructor Instructor { get; set; } = new();
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments =
        [
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
        ];

        var instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor", Bio = "Specializes in distributed systems and cloud computing. Published over 50 papers in top-tier conferences.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Bob Martinez", Title = "Associate Professor", Bio = "Expert in machine learning and artificial intelligence with 15 years of industry experience.", Email = "bmartinez@university.edu" },
            new() { Id = 3, Name = "Dr. Carol Thompson", Title = "Professor", Bio = "Number theorist with a passion for making abstract mathematics accessible to undergraduates.", Email = "cthompson@university.edu" },
            new() { Id = 4, Name = "Dr. David Park", Title = "Assistant Professor", Bio = "Researcher in quantum mechanics and particle physics. Previously at CERN.", Email = "dpark@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Rogers", Title = "Professor", Bio = "Award-winning author and literary critic specializing in modern American fiction.", Email = "erogers@university.edu" },
        };

        _courses =
        [
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", DepartmentId = 1, Department = _departments[0], Instructor = instructors[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures & Algorithms", Description = "Advanced study of data organization and algorithm design. Topics include trees, graphs, dynamic programming, and complexity analysis.", Credits = 4, Schedule = "TTh 10:30–11:50 AM", DepartmentId = 1, Department = _departments[0], Instructor = instructors[0], IsFeatured = false },
            new() { Id = 3, Code = "CS 420", Title = "Machine Learning", Description = "Introduction to machine learning techniques including supervised and unsupervised learning, neural networks, and model evaluation.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", DepartmentId = 1, Department = _departments[0], Instructor = instructors[1], IsFeatured = true },
            new() { Id = 4, Code = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, and eigenvalues. Essential for advanced science and engineering courses.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", DepartmentId = 2, Department = _departments[1], Instructor = instructors[2], IsFeatured = false },
            new() { Id = 5, Code = "MATH 301", Title = "Abstract Algebra", Description = "Introduction to groups, rings, and fields. Explores the structure of algebraic systems.", Credits = 3, Schedule = "TTh 2:00–3:20 PM", DepartmentId = 2, Department = _departments[1], Instructor = instructors[2], IsFeatured = false },
            new() { Id = 6, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "MWF 10:00–10:50 AM + Lab F 2:00–4:00 PM", DepartmentId = 3, Department = _departments[2], Instructor = instructors[3], IsFeatured = true },
            new() { Id = 7, Code = "PHYS 305", Title = "Quantum Mechanics", Description = "Introduction to quantum theory including wave functions, the Schrödinger equation, and quantum measurement.", Credits = 3, Schedule = "TTh 9:00–10:20 AM", DepartmentId = 3, Department = _departments[2], Instructor = instructors[3], IsFeatured = false },
            new() { Id = 8, Code = "ENG 102", Title = "College Writing", Description = "Develop clear, effective academic writing skills through essays, research papers, and peer review.", Credits = 3, Schedule = "MWF 10:00–10:50 AM", DepartmentId = 4, Department = _departments[3], Instructor = instructors[4], IsFeatured = false },
            new() { Id = 9, Code = "ENG 350", Title = "American Literature", Description = "Survey of American literature from the Colonial period to the present, examining themes of identity, freedom, and democracy.", Credits = 3, Schedule = "TTh 1:00–2:20 PM", DepartmentId = 4, Department = _departments[3], Instructor = instructors[4], IsFeatured = true },
        ];
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && request.CourseId > 0
            && _courses.Any(c => c.Id == request.CourseId);
    }
}

