    {
        // Check if this is a POST (form was submitted)
        if (!string.IsNullOrWhiteSpace(Model.StudentName) || !string.IsNullOrWhiteSpace(Model.StudentId) || Model.CourseId > 0)
        {
            if (string.IsNullOrWhiteSpace(Model.StudentName) || string.IsNullOrWhiteSpace(Model.StudentId) || Model.CourseId == 0)
            {
                validationError = "Please fill in all fields.";
                return;
            }

            if (Catalog.SubmitEnrollmentRequest(Model))
            {
                submitted = true;
            }
            else
            {
                validationError = "Invalid request. Please verify your information and try again.";
            }
        }
    }
}

